# Independent median-limit and synthetic hg38 model calls; original functions stay unchanged.
a<-commandArgs(TRUE);out<-a[1];source<-a[2];old<-a[3];.libPaths(c(a[-(1:3)],.Library),include.site=FALSE);suppressPackageStartupMessages(library(dndscv));original<-new.env(parent=asNamespace("dndscv"));for(p in list.files(file.path(source,"R"),pattern="[.]R$",full.names=TRUE))sys.source(p,original,keep.source=FALSE);guard<-function()for(n in Filter(function(n)is.function(get(n,original,inherits=FALSE)),ls(original,all.names=TRUE))){x<-get(n,original,inherits=FALSE);y<-get(n,asNamespace("dndscv"),inherits=FALSE);stopifnot(identical(formals(x),formals(y)),identical(body(x),body(y)))};guard();Sys.setlocale("LC_COLLATE","C");RNGkind("Mersenne-Twister","Inversion","Rejection");set.seed(190731)
