tsv<-function(frame,path){con<-file(path,open="wb");on.exit(close(con));writeLines(enc2utf8(paste(names(frame),collapse="\t")),con,useBytes=TRUE);if(nrow(frame))writeLines(enc2utf8(vapply(seq_len(nrow(frame)),function(i)paste(vapply(frame,function(c)if(is.double(c[i]))sprintf("%.17g",c[i]) else as.character(c[i]),character(1)),collapse="\t"),character(1))),con,useBytes=TRUE)}
base<-readRDS(file.path(old,"targeted-192/arguments.rds"));baseline<-readRDS(file.path(old,"targeted-192/original-return.rds"));cutoff<-as.integer(median(table(baseline$annotmuts$sampleID)));stopifnot(cutoff>10);median_args<-base;median_args$max_coding_muts_per_sample<-cutoff;median_args$max_muts_per_gene_per_sample<-3
data("refcds_GRCh38_hg38",package="dndscv");genes<-vapply(RefCDS,function(g)g$gene_name,character(1))[seq_len(75)];generated<-list();comp<-c(A="T",C="G",G="C",T="A");for(g in RefCDS[seq_len(75)]){cds<-strsplit(as.character(g$seq_cds),"")[[1]];up<-strsplit(as.character(g$seq_cds1up),"")[[1]];down<-strsplit(as.character(g$seq_cds1down),"")[[1]];good<-which(cds %in% c("A","C","G","T")&up %in% c("A","C","G","T")&down %in% c("A","C","G","T"));n<-min(length(good),max(6L,rpois(1,length(cds)*.004*rgamma(1,1,1))));chosen<-sample(good,n,replace=FALSE);positions<-unlist(apply(g$intervals_cds,1,function(x)seq(x[1],x[2])));if(g$strand==-1)positions<-rev(positions);for(j in seq_along(chosen)){i<-chosen[j];ref<-cds[i];alt<-sample(setdiff(c("A","C","G","T"),ref),1);if(g$strand==-1){ref<-unname(comp[ref]);alt<-unname(comp[alt])};generated[[length(generated)+1L]]<-data.frame(sampleID=paste0("synthetic-",j%%40),chr=as.character(g$chr),pos=positions[i],ref=ref,mut=alt,stringsAsFactors=FALSE)}}
hg38_args<-base;hg38_args$mutations<-do.call(rbind,generated);hg38_args$gene_list<-genes;hg38_args$refdb<-"hg38";hg38_args$cv<-"hg19_hg38_epigenome_pcawg";hg38_args$sm<-"2r_3w";definitions<-list(list(id="sample-event-limit-median",arguments=median_args,scope="Explicit synthetic control cutoff from the saved complete mapped-event distribution; the earlier cutoff10 all-excluded failure is retained."),list(id="hg38-standard-code-synthetic-events",arguments=hg38_args,scope="Synthetic independent software events generated from75 exact hg38 reference CDSs with seed190731, gamma/Poisson heterogeneous counts, canonical genomic contexts and both strands. No biological calibration or coordinate lift-over is claimed."));reports<-list()
for(case in definitions){home<-file.path(out,case$id);dir.create(home);dir.create(file.path(home,"inputs"));arguments<-case$arguments;saveRDS(arguments,file.path(home,"arguments.rds"),version=3);frame<-arguments$mutations[,1:5];names(frame)<-c("sample_id","chromosome","position","reference","alternate");tsv(frame,file.path(home,"inputs/mutations.tsv"));tsv(data.frame(gene_id=arguments$gene_list),file.path(home,"inputs/genes.tsv"));analysis<-list(id=case$id,seed=190731,substitution_model=arguments$sm,max_muts_per_gene_per_sample=if(is.infinite(arguments$max_muts_per_gene_per_sample))"Inf" else arguments$max_muts_per_gene_per_sample,max_coding_muts_per_sample=if(is.infinite(arguments$max_coding_muts_per_sample))"Inf" else arguments$max_coding_muts_per_sample,use_indel_sites=arguments$use_indel_sites,minimum_indels=arguments$min_indels,maximum_covariates=arguments$maxcovs,constrain_truncation=arguments$constrain_wnon_wspl,output="global-local-cv",minimum_genes_for_covariates=arguments$mingenecovs,one_sided=arguments$onesided,gene_set_comparison=FALSE);json(list(mutations="inputs/mutations.tsv",reference=list(kind="builtin",assembly=arguments$refdb,opportunities="verify-unweighted-standard-code"),genes=list(kind="supplied",file="inputs/genes.tsv",cdkn2a_policy="source-expand-isoforms"),covariates=list(kind="builtin",name=arguments$cv),known_cancer_genes=list(kind="builtin",name="cgc81"),duplex=list(kind="none"),analyses=list(analysis)),file.path(home,"runtime-input.json"));guard();set.seed(190731);warnings<-messages<-character();error<-NULL;result<-tryCatch(withCallingHandlers(do.call(dndscv::dndscv,arguments),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")},message=function(m){messages<<-c(messages,conditionMessage(m));invokeRestart("muffleMessage")}),error=function(e){error<<-conditionMessage(e);NULL});guard();if(!is.null(result))saveRDS(result,file.path(home,"original-return.rds"),version=3);record<-list(id=case$id,returned=!is.null(result),error=error,warnings=as.list(warnings),messages=as.list(messages),scope=case$scope,explicit_sample_event_limit=if(is.infinite(arguments$max_coding_muts_per_sample))"Inf" else arguments$max_coding_muts_per_sample);reports[[length(reports)+1L]]<-record;json(record,file.path(home,"status.json"));cat(case$id,record$returned,error,"\n")}
json(list(status="captured-original-dndscv-edge-controls-not-adapter-validation",source_bodies_and_formals_checked_before_and_after=TRUE,cases=reports),file.path(out,"controls.json"))
